+    public Message send(String to, String subject, String body) {
+        Message original = next.send(to, subject, body);
+        if (original.status() == MessageStatus.SENT) {
+            next.send(ARCHIVE_EMAIL, "[Cópia] " + subject, body);
+        }
+        return original;
+    }
+}
